window.TASK1_TIPS = {
 "IELTS Academic Writing Task 1: Practice Bank": "<p>18 practice questions covering every Task 1 type. All data is <strong>invented for practice</strong>. Each question now has a <strong>chart image</strong>: write from the chart, and use the table or list under it only to check your numbers afterwards. Also practise with real past papers (Cambridge IELTS Academic 1–19) and the free British Council/IDP tests listed in <code>IELTS-PREP.md</code>.</p>\n<p>Your test is <strong>computer-based</strong>, so <strong>type</strong> every answer, don't handwrite it.</p>\n<h2>How to use this file</h2>\n<ol>\n<li>Set a timer for <strong>20 minutes</strong> per question (2 min plan → 15 min write → 3 min check).</li>\n<li>Write <strong>170–190 words</strong>.</li>\n<li>Before writing, answer the \"Spot before you write\" questions in your head.</li>\n<li>After writing, open the <strong>Overview hint</strong> to check you found the main features.</li>\n<li>Go through the <strong>checklist</strong> at the bottom.</li>\n</ol>\n<h2>The formula (every question)</h2>\n<table>\n<thead>\n<tr>\n<th>Paragraph</th>\n<th>Content</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. Introduction</td>\n<td>Paraphrase the question (1 sentence)</td>\n</tr>\n<tr>\n<td>2. Overview</td>\n<td>2 main features, <strong>no numbers</strong></td>\n</tr>\n<tr>\n<td>3. Body 1</td>\n<td>Details + numbers, grouped logically</td>\n</tr>\n<tr>\n<td>4. Body 2</td>\n<td>Details + numbers, with comparisons</td>\n</tr>\n</tbody>\n</table>\n<p>No conclusion. No opinions. No reasons (\"because…\").</p>\n<h2>Contents</h2>\n<table>\n<thead>\n<tr>\n<th>#</th>\n<th>Type</th>\n<th>Topic</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1</td>\n<td>Line graph (past)</td>\n<td>Electricity production by source</td>\n</tr>\n<tr>\n<td>2</td>\n<td>Line graph (with future projection)</td>\n<td>Population aged 65+</td>\n</tr>\n<tr>\n<td>3</td>\n<td>Bar chart (two years)</td>\n<td>Teenagers' weekly activities</td>\n</tr>\n<tr>\n<td>4</td>\n<td>Bar chart (categories, no time)</td>\n<td>Men and women in professions</td>\n</tr>\n<tr>\n<td>5</td>\n<td>Pie chart (single)</td>\n<td>Reasons for choosing a university</td>\n</tr>\n<tr>\n<td>6</td>\n<td>Pie charts (comparison)</td>\n<td>Household spending 1980 vs 2020</td>\n</tr>\n<tr>\n<td>7</td>\n<td>Table (over time)</td>\n<td>Museum visitors</td>\n</tr>\n<tr>\n<td>8</td>\n<td>Table (static comparison)</td>\n<td>Public transport in four cities</td>\n</tr>\n<tr>\n<td>9</td>\n<td>Process (man-made)</td>\n<td>Recycling glass bottles</td>\n</tr>\n<tr>\n<td>10</td>\n<td>Process (natural cycle)</td>\n<td>Life cycle of a dragonfly</td>\n</tr>\n<tr>\n<td>11</td>\n<td>Diagram (how something works)</td>\n<td>Solar water heater</td>\n</tr>\n<tr>\n<td>12</td>\n<td>Process (manufacturing)</td>\n<td>Making chocolate</td>\n</tr>\n<tr>\n<td>13</td>\n<td>Maps (past vs present)</td>\n<td>Village of Westbury</td>\n</tr>\n<tr>\n<td>14</td>\n<td>Map (two proposed sites)</td>\n<td>New supermarket in Ashford</td>\n</tr>\n<tr>\n<td>15</td>\n<td>Floor plan (present vs planned)</td>\n<td>Library renovation</td>\n</tr>\n<tr>\n<td>16</td>\n<td>Mixed: line graph + pie chart</td>\n<td>Tourists visiting a city</td>\n</tr>\n<tr>\n<td>17</td>\n<td>Mixed: bar chart + table</td>\n<td>Recycling and household waste</td>\n</tr>\n<tr>\n<td>18</td>\n<td>Mixed: two line graphs</td>\n<td>Car ownership and public transport use</td>\n</tr>\n</tbody>\n</table>",
 "LINE GRAPHS": "<p><strong>Tense:</strong> past simple for past data, and \"had + past participle\" for \"by 2010 it had…\". For future projections, use <em>is expected / predicted / projected to</em>.\n<strong>Key skill:</strong> describing trends (rise, fall, peak, fluctuate, level off) and lines that cross.</p>",
 "BAR CHARTS": "<p><strong>Two kinds:</strong> bars over time (describe change) and bars by category with no time (describe and compare only, with no trend words).</p>",
 "PIE CHARTS": "<p><strong>Key language:</strong> <em>accounted for, made up, constituted, represented, the largest/smallest share, a quarter, just under half.</em></p>",
 "TABLES": "<p><strong>Trap:</strong> too many numbers. Never describe every cell. Find the overall pattern, then the exceptions.</p>",
 "PROCESSES AND DIAGRAMS": "<p><strong>Tense:</strong> present simple. Use the <strong>passive</strong> for man-made processes (\"is heated\") and the <strong>active</strong> for natural ones (\"the egg hatches\").\n<strong>Sequence words:</strong> <em>first, initially, next, then, after that, subsequently, once…, at this stage, finally</em>.\n<strong>Overview:</strong> number of stages + start and end point + whether it is cyclical (linear vs cycle).\n<strong>Group stages:</strong> split the process into 2 halves for your two body paragraphs.</p>",
 "MAPS AND PLANS": "<p><strong>Past → present maps:</strong> past simple or present perfect passive (\"was demolished\", \"has been replaced\").\n<strong>Proposed plans:</strong> future and conditional (\"will be built\", \"would be located\").\n<strong>Location language:</strong> <em>to the north/south/east/west of, in the north-east corner, next to, opposite, alongside, across from, between X and Y.</em>\n<strong>Change language:</strong> <em>was replaced by, was converted into, was demolished, was extended, was cleared to make way for, was relocated to, remained unchanged.</em>\n<strong>Overview:</strong> the overall nature of the change (more developed, more residential, more modern) + what stayed the same.</p>",
 "MIXED CHARTS (TWO CHARTS IN ONE QUESTION)": "<p><strong>Key skill:</strong> describe each chart in its own body paragraph, but your overview must mention <strong>both</strong> charts (one main feature from each, or a link between them).</p>",
 "LANGUAGE BANK": "<h2>Trends</h2>\n<table>\n<thead>\n<tr>\n<th>Up</th>\n<th>Down</th>\n<th>No change</th>\n<th>Up and down</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>rose, increased, climbed, grew</td>\n<td>fell, declined, dropped, decreased</td>\n<td>remained stable, stayed constant, levelled off, plateaued</td>\n<td>fluctuated, varied</td>\n</tr>\n<tr>\n<td>surged, soared (big)</td>\n<td>plunged, plummeted (big)</td>\n<td>—</td>\n<td>peaked at, hit a high of</td>\n</tr>\n<tr>\n<td>doubled, tripled, more than doubled</td>\n<td>halved, fell by a third</td>\n<td>—</td>\n<td>hit a low of, bottomed out at</td>\n</tr>\n</tbody>\n</table>\n<p><strong>Adverbs:</strong> sharply, dramatically, significantly, considerably (big) · steadily, gradually (medium) · slightly, marginally (small).</p>\n<p><strong>Noun form (adds variety):</strong> <em>There was </em><em>a sharp rise in</em><em> X</em> · <em>X saw </em><em>a gradual decline</em><strong> · <em>X experienced **a slight drop</em></strong>.</p>\n<h2>Approximation</h2>\n<p>just over · just under · nearly · almost · roughly · approximately · around · well over · exactly</p>\n<h2>Proportions</h2>\n<p>a quarter (25%) · a third (33%) · just under half (48%) · the majority (60%+) · a small minority (5–10%) · two in five (40%) · one in ten (10%)</p>\n<h2>Comparing</h2>\n<ul>\n<li>X was <strong>twice as high as</strong> Y</li>\n<li>X was <strong>considerably higher than</strong> Y</li>\n<li>X was <strong>the highest</strong>, <strong>followed by</strong> Y</li>\n<li><strong>By contrast</strong>, … · <strong>whereas</strong> … · <strong>while</strong> … · <strong>Similarly</strong>, …</li>\n<li><strong>The figure for</strong> X stood at …</li>\n<li>X <strong>and</strong> Y <strong>were similar</strong>, at around …</li>\n</ul>\n<h2>Tense guide</h2>\n<table>\n<thead>\n<tr>\n<th>Situation</th>\n<th>Tense</th>\n<th>Example</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Past dates</td>\n<td>Past simple</td>\n<td>Sales <strong>rose</strong> in 2010.</td>\n</tr>\n<tr>\n<td>Change up to a past point</td>\n<td>Past perfect</td>\n<td>By 2010, sales <strong>had doubled</strong>.</td>\n</tr>\n<tr>\n<td>No date / present</td>\n<td>Present simple</td>\n<td>Nursing <strong>is</strong> dominated by women.</td>\n</tr>\n<tr>\n<td>Future projection</td>\n<td><em>is expected / predicted to</em></td>\n<td>It <strong>is predicted to reach</strong> 20%.</td>\n</tr>\n<tr>\n<td>Process (man-made)</td>\n<td>Present simple passive</td>\n<td>The beans <strong>are roasted</strong>.</td>\n</tr>\n<tr>\n<td>Process (natural)</td>\n<td>Present simple active</td>\n<td>The eggs <strong>hatch</strong>.</td>\n</tr>\n<tr>\n<td>Map (past → now)</td>\n<td>Past simple / present perfect passive</td>\n<td>The forest <strong>was cleared</strong> / <strong>has been replaced</strong>.</td>\n</tr>\n<tr>\n<td>Planned map</td>\n<td>Future passive</td>\n<td>A café <strong>will be added</strong>.</td>\n</tr>\n</tbody>\n</table>",
 "SELF-CHECK CHECKLIST": "<p>After every answer, check:</p>\n<ul>\n<li>[ ] Introduction paraphrases the question (not copied)</li>\n<li>[ ] <strong>Overview present</strong>, 2 main features, no numbers</li>\n<li>[ ] Overview mentions the biggest change in <strong>ranking</strong> (who was top before vs after)</li>\n<li>[ ] Body paragraphs <strong>compare</strong>, not just list</li>\n<li>[ ] Numbers are accurate (<em>just over / nearly</em>)</li>\n<li>[ ] Correct tense throughout, with no switching</li>\n<li>[ ] No opinion, no reasons, no conclusion</li>\n<li>[ ] No informal words (<em>got, a lot, huge, scoring, that's</em>)</li>\n<li>[ ] No comma splices (two sentences joined by a comma)</li>\n<li>[ ] 170–190 words</li>\n<li>[ ] Finished in 20 minutes</li>\n</ul>\n<h2>Mistakes to avoid (from your first practice)</h2>\n<table>\n<thead>\n<tr>\n<th>❌ Don't</th>\n<th>✅ Do</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>Describe the axes</td>\n<td>Skip it</td>\n</tr>\n<tr>\n<td>\"scoring 6 million\"</td>\n<td>\"at / with / accounting for 6 million\"</td>\n</tr>\n<tr>\n<td>\"got halved\", \"got lowered\"</td>\n<td>\"halved\", \"fell\", \"dropped\"</td>\n</tr>\n<tr>\n<td>\"has increased\" (for past data)</td>\n<td>\"increased\"</td>\n</tr>\n<tr>\n<td>\"two-folds\"</td>\n<td>\"more than doubled\" / \"twofold\"</td>\n</tr>\n<tr>\n<td>\"mean of transport\"</td>\n<td>\"means of transport\"</td>\n</tr>\n<tr>\n<td>\"…decline, it scores…\"</td>\n<td>\"…decline. It fell…\"</td>\n</tr>\n</tbody>\n</table>"
};
